proc publish*(s: ModuleServices, event: LedgerPostedEvent): Result[void, InvocationFailure] =
  ## Publishes `ledger.posted_event` through the instance's publish callback.
  let data = encode(event).valueOr:
    return err(moduleError("the event does not match its schema: " & error))
  s.publishEncoded("ledger.posted_event", data)

proc publishScoped*(s: ModuleServices, event: LedgerPostedEvent): Result[void, InvocationFailure] =
  ## Publishes `ledger.posted_event` through the active provider entry (INTERFACE §2.9.3).
  let data = encode(event).valueOr:
    return err(moduleError("the event does not match its schema: " & error))
  s.publishScopedEncoded("ledger.posted_event", data)

proc publishAsync*(s: ModuleServices, event: LedgerPostedEvent): Future[Result[void, InvocationFailure]] {.async: (raises: []).} =
