proc routeConfinedLedgerModule[T](instance: T, bare: string, params: ptr UncheckedArray[uint8], len: int, inv: Invocation): Future[Result[seq[byte], InvocationFailure]] {.async: (raises: []).} =
  mixin `post`, `probe`, `seal`, `wait`
  var request = kitValidator().checkedRequestAt(bare, params, len)
  if request.isErr:
    return Result[seq[byte], InvocationFailure].err(request.unsafeError)
  if bare == "post":
    var typed = fromChecked(LedgerPostRequest, request.unsafeGet)
    var response: Result[LedgerPostResponse, InvocationFailure]
    when compiles(`post`(instance, typed, inv)):
      settleHandler(response, `post`(instance, typed, inv), inv)
    else:
      let saved = enterPlain(inv)
      response = `post`(instance, typed)
      leavePlain(saved)
    if response.isErr:
      result = Result[seq[byte], InvocationFailure].err(response.unsafeError)
      return
    result = encodedResponse(encode(response.unsafeGet))
    return
  if bare == "probe":
    var typed = fromChecked(LedgerProbeRequest, request.unsafeGet)
    var response: Result[LedgerProbeResponse, InvocationFailure]
    when compiles(`probe`(instance, typed, inv)):
      settleHandler(response, `probe`(instance, typed, inv), inv)
    else:
      let saved = enterPlain(inv)
      response = `probe`(instance, typed)
      leavePlain(saved)
    if response.isErr:
